    CREATE TABLE [Geo].[Country]
    (
        [Id] BIGINT NOT NULL,
        [CountryCode] NVARCHAR(8) NOT NULL,
        [NameFa] NVARCHAR(150) NOT NULL,
        [NameEn] NVARCHAR(150) NOT NULL,
        CONSTRAINT [PK_Geo_Country] PRIMARY KEY ([Id]),
        CONSTRAINT [UQ_Geo_Country_CountryCode] UNIQUE ([CountryCode])
    );
    CREATE TABLE [Geo].[Province]
    (
        [Id] BIGINT NOT NULL,
        [IdCountry] BIGINT NOT NULL,
        [NameFa] NVARCHAR(150) NOT NULL,
        [NameEn] NVARCHAR(150) NOT NULL,
        [Latitude] DECIMAL(12,8) NULL,
        [Longitude] DECIMAL(12,8) NULL,
        CONSTRAINT [PK_Geo_Province] PRIMARY KEY ([Id]),
        CONSTRAINT [FK_Geo_Province_Country] FOREIGN KEY ([IdCountry]) REFERENCES [Geo].[Country] ([Id]),
        CONSTRAINT [UQ_Geo_Province_Country_Name] UNIQUE ([IdCountry], [NameFa])
    );
    CREATE TABLE [Geo].[City]
    (
        [Id] BIGINT NOT NULL,
        [IdCountry] BIGINT NOT NULL,
        [IdProvince] BIGINT NOT NULL,
        [SourceCountryName] NVARCHAR(200) NOT NULL,
        [NameFa] NVARCHAR(200) NOT NULL,
        [NameEn] NVARCHAR(200) NOT NULL,
        [Latitude] DECIMAL(12,8) NULL,
        [Longitude] DECIMAL(12,8) NULL,
        [IsProvinceCenter] BIT NOT NULL CONSTRAINT [DF_Geo_City_IsProvinceCenter] DEFAULT (0),
        CONSTRAINT [PK_Geo_City] PRIMARY KEY ([Id]),
        CONSTRAINT [FK_Geo_City_Country] FOREIGN KEY ([IdCountry]) REFERENCES [Geo].[Country] ([Id]),
        CONSTRAINT [FK_Geo_City_Province] FOREIGN KEY ([IdProvince]) REFERENCES [Geo].[Province] ([Id])
    );
    CREATE INDEX [IX_Geo_City_Province_Name] ON [Geo].[City] ([IdProvince], [NameFa]);
